285: func treeEqual(tr1, tr2 *Tree) bool {
286: 	switch {
287: 	case tr1 == nil && tr2 == nil:
288: 		return true
289: 	case tr1 == nil && tr2 != nil:
290: 		return false
291: 	case tr1 != nil && tr2 == nil:
292: 		return false
293: 	default:
294: 		return tr1.Value() == tr2.Value() && treeSliceEqual(tr1.Children(), tr2.Children())
295: 	}
296: }
297: 
298: func treeSliceEqual(trs1, trs2 []*Tree) bool {
299: 	// allows permutation of children
300: 	if len(trs1) != len(trs2) {
301: 		return false
302: 	}
303: 	if len(trs1) == 0 && len(trs2) == 0 {
304: 		return true
305: 	}
306: 	sortByValue := func(xs []*Tree) func(int, int) bool {
307: 		return func(i, j int) bool {
308: 			return xs[i].Value() < xs[j].Value()
309: 		}
310: 	}
311: 	sort.Slice(trs1, sortByValue(trs1))
312: 	sort.Slice(trs2, sortByValue(trs2))
313: 	for i := range trs1 {
314: 		if !treeEqual(trs1[i], trs2[i]) {
315: 			return false
316: 		}
317: 	}
318: 	return true
319: }
320: 
321: func stringSliceEqual(a, b []string) bool {
322: 	if len(a) != len(b) {
323: 		return false
324: 	}
325: 	if len(a) == 0 {
326: 		return true
327: 	}
328: 	for i := 0; i < len(a); i++ {
329: 		if a[i] != b[i] {
330: 			return false
331: 		}
332: 	}
333: 	return true
334: }

