package pov

// Tree is a node in an unordered tree.
type Tree struct {
	value    string
	children []*Tree
}

// New creates and returns a new Tree with the given root value and children.
func New(value string, children ...*Tree) *Tree {
	return &Tree{value: value, children: children}
}

// Value returns the value at the root of a tree.
func (tr *Tree) Value() string {
	return tr.value
}

// Children returns a slice containing the children of a tree.
// There is no need to sort the elements in the result slice,
// they can be in any order.
func (tr *Tree) Children() []*Tree {
	return tr.children
}

// String describes a tree in a compact S-expression format.
// This helps to make test outputs more readable.
// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// POV problem-specific functions

// FromPov returns a copy of the tree re-oriented from the point of view of
// the node whose value is from, with that node as the new root.
// It returns nil if no node with that value exists.
func (tr *Tree) FromPov(from string) *Tree {
	if tr == nil {
		return nil
	}

	// Collect the chain of nodes from the current root down to the target.
	var chain []*Tree
	var find func(t *Tree) bool
	find = func(t *Tree) bool {
		if t.value == from {
			chain = append(chain, t)
			return true
		}
		for _, c := range t.children {
			if find(c) {
				chain = append(chain, t)
				return true
			}
		}
		return false
	}
	if !find(tr) {
		return nil
	}

	// Rebuild the tree bottom-up: each node keeps its off-path children and
	// gains the re-oriented subtree below it as an additional child.
	var result *Tree
	for i := len(chain) - 1; i >= 0; i-- {
		node := chain[i]
		children := make([]*Tree, 0, len(node.children)+1)
		for _, c := range node.children {
			if i < len(chain)-1 && c == chain[i+1] {
				continue // this child is on the path to the new root
			}
			children = append(children, c)
		}
		if result != nil {
			children = append(children, result)
		}
		result = New(node.value, children...)
	}
	return result
}

// PathTo returns the shortest path between the nodes with values from and to,
// as a slice of node values starting at from and ending at to.
// It returns nil if either node does not exist.
func (tr *Tree) PathTo(from, to string) []string {
	if tr == nil {
		return nil
	}
	root := tr.FromPov(from)
	if root == nil {
		return nil
	}

	var path []string
	var find func(t *Tree) bool
	find = func(t *Tree) bool {
		path = append(path, t.value)
		if t.value == to {
			return true
		}
		for _, c := range t.children {
			if find(c) {
				return true
			}
		}
		path = path[:len(path)-1]
		return false
	}
	if !find(root) {
		return nil
	}
	return path
}

